/* C API of the Rust port of `src/facade.c`, generated by rust-anything. */
#ifndef FACADE_RS_H
#define FACADE_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

long parse_long(const char *text, int base);
int parse_int(const char *text);
double parse_double(const char *text);
size_t span(const char *text, const char *accept);
int compare(const char *a, const char *b);
int is_alpha(int c);
int is_space(int c);
int is_punct(int c);
int to_upper(int c);

/* The same functions under `rust_anything_` names, for shadow runs. */
long rust_anything_parse_long(const char *text, int base);
int rust_anything_parse_int(const char *text);
double rust_anything_parse_double(const char *text);
size_t rust_anything_span(const char *text, const char *accept);
int rust_anything_compare(const char *a, const char *b);
int rust_anything_is_alpha(int c);
int rust_anything_is_space(int c);
int rust_anything_is_punct(int c);
int rust_anything_to_upper(int c);

#endif /* FACADE_RS_H */
